from pathlib import Path
import json,html
root=Path(__file__).resolve().parent;dist=root/'dist';config=json.loads((root/'site-config.json').read_text());esc=html.escape
email=config['support_email'].strip();draft=config['draft'];domain=config['domain'].strip()
if not draft and (not email or not domain):raise SystemExit('Confirm the support mailbox and website domain before preparing a public version.')
contact=(f'<a class="contact-email" href="mailto:{esc(email,quote=True)}">{esc(email)}</a>' if email else '<p class="contact-pending">Support email awaiting confirmation.</p>')
brand='<span class="brand" role="img" aria-label="Waist Time"><span>Waist</span><br><span>Time</span></span>'
banner='<div class="draft-banner">Website draft for Vicki’s review <span>•</span> Contact address supplied; review before publishing</div>' if draft else ''
header=lambda page:f'''{banner}<a class="skip" href="#main">Skip to content</a><header class="site-header wrap"><a class="brand-link" href="index.html" aria-label="Waist Time home">{brand}</a><nav aria-label="Main navigation"><a href="index.html#journey"{' aria-current="page"' if page=='home' else ''}>Your journey</a><a href="privacy.html"{' aria-current="page"' if page=='privacy' else ''}>Privacy</a><a class="nav-support" href="support.html"{' aria-current="page"' if page=='support' else ''}>Support</a></nav></header>'''
footer='''<footer class="site-footer"><div class="wrap footer-inner"><a class="footer-name" href="index.html">Waist Time</a><p>Every point tells part of the story.</p><nav aria-label="Footer navigation"><a href="privacy.html">Privacy Policy</a><a href="support.html">Support</a><a href="#top">Back to top ↑</a></nav><small>© 2026 Waist Time</small></div></footer>'''
def write(name,title,description,body,page):
 robots='<meta name="robots" content="noindex,nofollow">' if draft else ''
 text=f'''<!doctype html><html lang="en" id="top"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="description" content="{esc(description,quote=True)}">{robots}<title>{esc(title)} · Waist Time</title><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="stylesheet" href="styles.css"></head><body>{header(page)}{body}{footer}</body></html>'''
 (dist/name).write_text(text)
write('index.html','Your journey, one day at a time','A gentle place for your weights, measurements, medical records and milestones. Learn about Waist Time, privacy and support.',f'''
<main id="main"><section class="hero wrap" aria-labelledby="hero-heading"><div class="hero-copy"><p class="eyebrow">YOUR PROGRESS. YOUR PACE.</p><h1 id="hero-heading">Every point tells<br>part of the <em>story.</em></h1><p class="hero-lede">A gentle place to see your progress over time.</p><p class="hero-description">Bring your weights, measurements, medical records and milestones together. Make room for the little changes, the big moments, and everything in between.</p><a class="button" href="#journey">Discover Waist Time <span aria-hidden="true">↗</span></a><p class="availability">Currently in private testing.</p></div><figure class="hero-art"><img src="assets/waist-time-woman.png" width="1144" height="1375" alt="Waist Time’s watercolor illustration: a woman with a measuring tape and flowers"><figcaption>Each day tells a story.</figcaption></figure></section>
<section id="journey" class="story-section"><div class="wrap"><div class="section-intro"><p class="eyebrow">A PLACE FOR YOUR JOURNEY</p><h2>More than a number.<br><em>A picture of your progress.</em></h2><p>See your entries over time, keep your notes close, and recognize what you’ve accomplished.</p></div><div class="editorial-grid"><article class="feature"><span class="feature-number">01</span><div><h3>Weights &amp; measurements</h3><p>Record your weights and goal, follow your graph, and keep body measurements together with the notes that give them meaning.</p></div></article><article class="feature"><span class="feature-number">02</span><div><h3>Medical, in one place</h3><p>Keep medication details, doses and history alongside your doctor appointments. Appointments have their own home on the Medical page.</p></div></article><article class="feature"><span class="feature-number">03</span><div><h3>Milestones worth remembering</h3><p>Celebrate milestones you’ve reached and keep track of the things you’re looking forward to.</p></div></article><article class="feature"><span class="feature-number">04</span><div><h3>Look back with My Journey</h3><p>Find your weights, measurements, doses and milestones in a timeline. Your own entries tell the story.</p></div></article></div></div></section>
<section class="milestone-moment wrap"><p class="handwritten">They used to be goals. Now they’re…</p><h2>Milestones!</h2><p>There’s room to celebrate the progress that matters to you.</p></section>
<section class="care-section"><div class="wrap care-grid"><div><p class="eyebrow">KNOW WHERE YOUR RECORDS LIVE</p><h2>Your entries, across devices.<br><em>Your photos, on their own device.</em></h2></div><div class="care-copy"><p>Sign in with the same email address on your devices to connect them to one Waist Time account and synchronize your entries, notes and goal.</p><p><strong>Photos stay on the device where you add them.</strong> They do not sync through Waist Time. Keep original photos backed up outside the app, especially before replacing a device or removing the app.</p><a class="text-link" href="privacy.html">Read the Privacy Policy <span aria-hidden="true">→</span></a></div></div></section>
<section class="faq-section wrap"><div><p class="eyebrow">A FEW HELPFUL THINGS</p><h2>A little clarity<br>before you begin.</h2></div><div class="faq-list"><details><summary>How do I get access?</summary><p>During beta testing, Waist Time is available to invited testers. Please use the email address associated with your invitation. Account setup is arranged through Waist Time Support; this website does not offer public downloads or self-service sign-up.</p><a class="text-link" href="support.html">Visit Support →</a></details><details><summary>Will my photos appear on another device?</summary><p>No. Photos, thumbnails and their details stay on the device where you add them. Signing in on another device brings back entries that have synchronized, while your photo album stays on its own device.</p></details><details><summary>What should I do before deleting the app?</summary><p>Make sure your entries have synchronized, review any questions about two versions, and preserve your original photos and important photo notes separately. Deleting the app can remove local photos and changes that never reached the cloud.</p></details><details><summary>Does Waist Time provide medical advice?</summary><p>Waist Time is a personal recordkeeping app. It does not diagnose conditions or replace advice from your healthcare professional. Follow your prescriber’s instructions for medication.</p></details></div></section>
<section class="closing wrap"><p class="handwritten">A little progress. A little perspective.</p><h2>Your story belongs to you.</h2><a class="button button-light" href="support.html">Find help &amp; support <span aria-hidden="true">→</span></a></section></main>''','home')
write('support.html','Support','Help with Waist Time sign-in, synced entries, local photos and privacy requests.',f'''
<main id="main"><section class="document-hero wrap"><p class="eyebrow">WE’RE HERE TO HELP</p><h1>Support</h1><p class="hero-lede">A little help for the next step.</p></section><div class="document-layout wrap"><aside class="document-aside"><p class="handwritten">Your questions<br>have a home here.</p><a href="#contact">Contact</a><a href="#sign-in">Signing in</a><a href="#records">Entries &amp; photos</a><a href="#privacy-help">Privacy requests</a></aside><div class="document-copy"><section id="contact"><h2>Get in touch</h2><p>For help with Waist Time, your account, or a privacy question, use the support contact below.</p>{contact}<p class="small">Please don’t send passwords, email sign-in codes, or sensitive health screenshots. Start with a description of the problem, your device model and the app version.</p></section><section id="sign-in"><h2>Signing in</h2><p>During beta testing, Waist Time is available to invited testers. Please use the email address associated with your invitation. Enter the newest code sent to that address in the app. If it hasn’t arrived, check spam or junk and confirm the email address is spelled correctly.</p><p>Sign in with the same email address on all your devices. This connects them to the same Waist Time account so your information can synchronize between them.</p><p>If you use different email addresses, Waist Time treats them as separate accounts, and your information won’t automatically appear across those accounts. Each person should have a separate account. If the app says your account is not enabled for syncing, contact Waist Time Support rather than using someone else’s account.</p></section><section id="records"><h2>Entries and photos</h2><h3>If an entry hasn’t appeared on another device</h3><p>Check that both devices have an internet connection and are signed in with the same email address. Leave Waist Time open while it connects. An entry saved without internet may still be waiting to synchronize.</p><p>If Waist Time asks you to choose between two versions of an entry, read both carefully before choosing.</p><h3>Before deleting or reinstalling</h3><p>Do not remove the app as a first troubleshooting step. Local photos, their details and changes that never uploaded may be lost. Keep original photos in your own backed-up Photos or Files library.</p><h3>On a new device</h3><p>Sign in to the same account to bring back entries that have synchronized successfully. Photo albums and display settings stay local and do not arrive through Waist Time’s cloud syncing.</p><h3>Deleted entries</h3><p>Check Recently Deleted if you removed an entry by mistake. The usual recovery period is 15 days for entries that support Recently Deleted. Check that page to see which entries are still available; recovery safeguards can sometimes keep an entry longer. Permanent deletion removes the entry’s content from Waist Time’s active records. Waist Time has no supported way to recover a permanently deleted entry. An older provider backup, if one exists, is not an individual-entry recovery service.</p></section><section id="privacy-help"><h2>Privacy and account requests</h2><p>For questions or requests about your account information, contact Waist Time Support using the address above. Include the email you use for Waist Time, but never send a password or sign-in code.</p><p>Knowing an email address alone does not authorize access to or deletion of account information. Never send a sign-in code to Support.</p><p>Signing out, deleting an individual entry and uninstalling the app are different from deleting your cloud account.</p><a class="text-link" href="privacy.html">Read the Privacy Policy →</a></section><section><h2>TestFlight feedback</h2><p>Current testers can also send feedback through TestFlight. Review any attached screenshot so you share only what you intend. A screenshot may contain health details or identifiable photos.</p></section></div></div></main>''','support')
write('privacy.html','Privacy Policy','How Waist Time handles account information, synced records, local photos and privacy questions.',f'''
<main id="main"><section class="document-hero wrap"><p class="eyebrow">YOUR INFORMATION, EXPLAINED</p><h1>Privacy Policy</h1><p class="hero-lede">Understand what syncs, what stays local, and how to ask for help.</p><p class="policy-date">{'Draft for review' if draft else 'Last updated'} · {esc(config['policy_date'])}</p></section><div class="document-layout wrap"><aside class="document-aside"><a href="#information">Information</a><a href="#photos">Local photos</a><a href="#providers">Service providers</a><a href="#retention">Retention &amp; choices</a><a href="#privacy-contact">Contact</a></aside><article class="document-copy"><section><h2>About this policy</h2><p>This policy describes the current Waist Time private beta and this informational website. Waist Time helps you keep personal progress and medical records. It does not provide medical advice.</p></section><section id="information"><h2>Information used by the app</h2><p><strong>Account information.</strong> Your email address and an account identifier are used to sign you in, send sign-in codes and keep your synced records associated with your account.</p><p><strong>Records you choose to enter.</strong> The app can sync weights, goals, body measurements, medication details, doses, medication history, doctor appointments, completed and upcoming milestones, and associated notes and milestone appearance. These records may contain sensitive health information.</p><p>We use this information to provide account access, storage, syncing and recovery features. The app does not sell your records or use them for advertising or cross-app tracking.</p></section><section id="photos"><h2>Photos stay on your device</h2><p>Photo images, thumbnails and their details—including dates, optional weights and notes—are stored locally on the device where you add them. The app does not upload these to Supabase or sync them to your other devices.</p><p>Imported images are processed locally into app copies; source filenames and embedded location metadata are not copied into the album. The app’s copy may be resized or re-encoded. Your original photo library is not changed by import.</p><p><strong>Keep original photos backed up outside Waist Time.</strong> Deleting the app, losing a device or replacing a device can mean losing the local album and its details. Signing in again does not restore those photos through Supabase. Whether a device backup contains the album depends on that backup. Keep a separate copy of important photos rather than relying on the app to restore them.</p></section><section><h2>Information kept on your device</h2><p>Waist Time remembers your display preferences and saves changes that haven’t yet synchronized with your account.</p><p>For example, if you enter your weight without an internet connection, Waist Time keeps that information on your device until it can connect and synchronize. You need to be signed in to use your account’s entries.</p><p>Your sign-in information is stored securely using Apple’s built-in security features in the installed app. Signing out removes the saved sign-in from that device. It does not delete your entries or sign you out on your other devices.</p></section><section id="providers"><h2>Service providers</h2><p><strong>Supabase</strong> helps you sign in and stores the entries you choose to synchronize. Account checks keep each person’s synchronized information separate.</p><p><strong>Resend</strong> delivers sign-in emails for the configured sender. Those emails use your email address and the information needed to send your code; those messages do not include your health entries.</p><p><strong>Apple</strong> provides app distribution, device services and TestFlight feedback handling. If you send feedback or contact support and include a screenshot or photo, Waist Time Support receives what you choose to share through that channel.</p><p>These providers may process technical connection, security and delivery information needed to operate their services. Their policies and the service settings affect handling and retention.</p></section><section><h2>This website</h2><p>This informational website has no sign-in form, health-entry form, advertising scripts or analytics added by Waist Time. Links to external services are governed by those services’ own privacy practices.</p><p>The company hosting this website may receive connection information, such as an internet address and the pages requested, to deliver the website and help keep it secure.</p></section><section id="retention"><h2>Your information and your choices</h2><p>You can change information you’ve entered into Waist Time and delete entries using the app’s controls.</p><p>For entries that support Recently Deleted, the usual recovery period is 15 days. These include weights, measurements, doses, appointments, medication-history entries, completed and upcoming milestones, and photos. Check Recently Deleted to see what is still available to restore. Some entries may stay available longer when the app’s recovery safeguards apply.</p><p>Permanent deletion removes the entry’s content from Waist Time’s active records. Waist Time has no supported way to recover a permanently deleted entry. An older provider backup, if one exists, is not an individual-entry recovery service. Your original photos saved outside Waist Time are separate from the copies in the app.</p><p>Your entries synchronize between your devices when an internet connection is available. Synchronized entries stay in your account until they are deleted. Photos and display preferences stay on their own device.</p><p>If you enter information while offline, it stays on that device until it can synchronize. Information that hasn’t synchronized may be lost if the device is lost or erased.</p><p>Deleting Waist Time from your device does not automatically delete your account or information already stored in the cloud. Signing out is also different from deleting your account. Removing account access does not remotely erase information already saved on a device.</p><p>A small record that an entry was deleted may remain to help prevent it from reappearing when another device connects. This does not keep the deleted entry’s text or photo. If older provider backups exist, they may retain earlier copies until those backups expire. They are separate from Recently Deleted and do not promise recovery of an individual entry.</p><p>For questions about seeing, correcting or deleting your account information, contact Waist Time Support. Knowing an email address alone does not authorize access to or deletion of account information. Never send a sign-in code to Support. Privacy rights and any legal requirements to keep information can vary by location.</p></section><section><h2>Security</h2><p>The app protects information while it travels between your device and the cloud. Apple’s built-in security features protect saved sign-in information in the installed app, and account checks help keep each person’s synchronized entries separate.</p><p>No system can guarantee complete security. Protect your device and email account, and do not share sign-in codes. Your photo album does not have its own separate Face ID, Touch ID or password lock.</p></section><section><h2>Changes to this policy</h2><p>The policy will be updated when the app’s data practices change. The date shown above identifies the current version. Any future photo-sync feature would require an updated explanation before use.</p></section><section id="privacy-contact"><h2>Contact</h2><p>For support or a question about your information, contact Waist Time Support:</p>{contact}<a class="text-link" href="support.html">Visit Support →</a></section></article></div></main>''','privacy')
(dist/'robots.txt').write_text('User-agent: *\nDisallow: /\n' if draft else 'User-agent: *\nAllow: /\n')
print('Built home, privacy and support pages. Draft:',draft,'Contact confirmed:',bool(email),'Domain confirmed:',bool(domain))
